CREATE TABLE IF NOT EXISTS polls (id INTEGER PRIMARY KEY AUTOINCREMENT,question TEXT NOT NULL,created_at INTEGER NOT NULL,closes_at INTEGER NOT NULL,closed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS poll_options (poll_id INTEGER NOT NULL,option_id INTEGER NOT NULL,label TEXT NOT NULL,PRIMARY KEY(poll_id,option_id));
CREATE TABLE IF NOT EXISTS poll_votes (poll_id INTEGER NOT NULL,uuid TEXT NOT NULL,option_id INTEGER NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(poll_id,uuid));
